const contentStyle = { height: 100 }

function AccordionContent({ text }: { text: string }) {
  return (
    <div
      className="lyrixi-flex lyrixi-flex-justify-center lyrixi-flex-align-center lyrixi-border-b"
      style={contentStyle}
    >
      {text}
    </div>
  )
}

