import { Page, Cascader, Loading, type CascaderItem, type LoadDataResult } from 'lyrixi-mobile'

export default function CascaderMainDemo() {
  const [value, setValue] = useState<CascaderItem[]>([
    {
      id: '1',
      name: '\u6839\u8282\u70B9',
      parentid: null
    },
    {
      id: '1-1',
      name: '\u5B50\u8282\u70B9',
      parentid: '1'
    },
    {
      parentid: '1-1',
      name: '\u5B59\u5B50\u8282\u70B9',
      id: '1-1-1',
      isLeaf: true
    }
  ])

  function loadData(
    tabs: CascaderItem[],
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    _ctx: { list: CascaderItem[] }
  ): Promise<LoadDataResult> {
    return new Promise((resolve) => {
      console.log('loadData:', tabs)
      Loading.open()
      const lastTab = tabs?.[tabs.length - 1]
      const leaves: CascaderItem[] = [
        {
          parentid: lastTab?.id,
          name: '\u5B59\u5B50\u8282\u70B91',
          id: '1-1-1',
          isLeaf: true
        },
        {
          parentid: lastTab?.id,
          name: '\u5B59\u5B50\u8282\u70B92',
          id: '1-1-2',
          isLeaf: true
        }
      ]
      setTimeout(() => {
        Loading.close()
      }, 100)
      resolve({
        status: 'success',
        data: { list: leaves }
      })
    })
  }

  return (
    <Page>
      <Cascader.Main
        list={[
          {
            id: '1',
            name: '\u6839\u8282\u70B9',
            children: [
              {
                id: '1-1',
                name: '\u5B50\u8282\u70B9'
              }
            ]
          }
        ]}
        loadData={loadData}
        value={value}
        onChange={(newValue) => {
          console.log('\u4FEE\u6539:', newValue)
          setValue(newValue)
        }}
      />
    </Page>
  )
}
