import type { AssetUtilLoadRemoteJsParams } from '../types'

// \u52A8\u6001\u52A0\u8F7Dscript\u7684\u65B9\u6CD5
function loadRemoteJs(src: string, params?: AssetUtilLoadRemoteJsParams) {
  const {
    async,
    charset,
    text,
    type,
    id,
    defer,
    crossorigin,
    integrity,
    referrerPolicy,
    onError,
    onSuccess
  } = params || {}
  let attrs: Record<string, string> = {}
  if (id) attrs.id = id
  if (defer) attrs.defer = ''
  if (crossorigin) attrs.crossorigin = crossorigin
  if (integrity) attrs.integrity = integrity
  if (referrerPolicy) attrs.referrerPolicy = referrerPolicy

  return new Promise((resolve) => {
    loadScript(src, {
      async: async,
      charset: charset,
      text: text,
      type: type,
      attrs: attrs,
      onError: (result: unknown) => {
        resolve(result)
        // \u652F\u6301\u65B0\u7684 onError
        onError?.(result)
      },
      onSuccess: (result: unknown) => {
        resolve(result)
        // \u652F\u6301\u65B0\u7684 onSuccess
        onSuccess?.(result)
      }
    })
  })
}

export default loadRemoteJs
`}),91885:(function(l,n){"use strict";n.A=`// https://github.com/eldargab/load-script
import type { AssetUtilLoadScriptLegacyIEScript } from './loadScript.types'

function setAttributes(script: HTMLScriptElement, attrs: Record<string, string>) {
  // eslint-disable-next-line
  for (let attr in attrs) {
    script.setAttribute(attr, attrs[attr])
  }
}

function stdOnEnd(
  script: HTMLScriptElement,
  opts?: {
    onError?: (r: { status: string; script: HTMLScriptElement; message: string }) => void
    onSuccess?: (r: { status: string; script: HTMLScriptElement; message: string }) => void
  }
) {
  const { onError, onSuccess } = opts || {}
  script.onload = function () {
    this.onerror = this.onload = null
    onSuccess?.({
      status: 'success',
      script: script,
      message: ''
    })
  }
  script.onerror = function () {
    // this.onload = null here is necessary
    // because even IE9 works not like others
    this.onerror = this.onload = null
    onError?.({
      status: 'error',
      script: script,
      message: 'Failed to load ' + this.src
    })
  }
}

// there is no way to catch loading errors in IE8
function ieOnEnd(
  script: HTMLScriptElement,
  opts?: {
    onError?: (r: { status: string; script: HTMLScriptElement; message: string }) => void
    onSuccess?: (r: { status: string; script: HTMLScriptElement; message: string }) => void
  }
) {
  const {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    onError,
    onSuccess
  } = opts || {}
  const s = script as AssetUtilLoadScriptLegacyIEScript
  s.onreadystatechange = function () {
    if (this.readyState !== 'complete' && this.readyState !== 'loaded') return
    this.onreadystatechange = null
    onSuccess?.({
      status: 'success',
      script: script,
      message: ''
    })
  }
}

export default function loadScript(
  src: string,
  opts?: {
    type?: string
    async?: boolean
    text?: string
    charset?: string
    attrs?: Record<string, string>
    onError?: (r: { status: string; script: HTMLScriptElement; message: string }) => void
    onSuccess?: (r: { status: string; script: HTMLScriptElement; message: string }) => void
  }
) {
  const { type, async, text, charset, attrs, onError, onSuccess } = opts || {}
  let head = document.head || document.getElementsByTagName('head')[0]
  let script = document.createElement('script')

  script.type = type || 'text/javascript'
  script.async = Boolean(async)
  if (charset) {
    script.setAttribute('charset', charset)
  }
  script.src = src

  if (attrs) {
    setAttributes(script, attrs)
  }

  if (text) {
    script.text = '' + text
  }

  let onend = 'onload' in script ? stdOnEnd : ieOnEnd
  onend(script, { onError, onSuccess })

  // some good legacy browsers (firefox) fail the 'in' detection above
  // so as a fallback we always set onload
  // old IE will ignore this and new IE will set onload
  if (!script.onload) {
    stdOnEnd(script, { onError, onSuccess })
  }

  head.appendChild(script)
}
